                obnovPodlePuvodnihoFiltru() {
                    var that = this;
                    this.NactiData(this.posledniHledaneKriteria, null);
                }
                odstranitEx(aktivita, pocetTxt) {
                    var that = this;
                    var sel = that.gridKartoteka.ggrid("activeRow");
                    //var aktivita = sel.aktivita === 500 ? 100 : 500;
                    if (sel) {
                        var text = aktivita === 100 || pocetTxt === "nespecifikováno" ?
                            "jres:32115045 <br> " + sel.esu_txt + pocetTxt : //RC 32115045 : Přejete si skutečně odstranit externí subjekt:
                            "jres:32115046 <br> " + sel.esu_txt; //RC 32115046 : Přejete si skutečně obnovit externí subjekt:
                        this.dialogs.messageBox("jres:32115047", text, GDlg.mbbYesNo, GDlg.mbiQuestion) //RC 32115047 : Změna aktivity
                            .on("yes", function () {
                            that.zadaniDuvoduOdstraneni(sel.ixs_esu, aktivita);
                        });
                    }
                    else {
                        that.dialogs.alert("jres:31900144"); //RC 31900144 : Nebyl označen řádek
                    }
                }
                zadaniDuvoduOdstraneni(ixs_esu, aktivita) {
                    var that = this;
                    var l_sLabel = "jres:31900296"; //RC 31900296 : Zadejte důvod změny aktivity subjektu
                    this.dialogs.prompt("jres:31900298", l_sLabel).on("ok", function (ev, duvod) {
                        if (duvod && (duvod.trim() != "")) {
                            that.call("ZmenitAktivitu", { ixs_esu: ixs_esu, aktivita: aktivita === 500 ? 100 : 500, duvod: duvod })
                                .done(function (val) {
                                that.obnovPodlePuvodnihoFiltru();
                            })
                                .fail(function (val) {
                            });
                        }
                        else {
                            that.dialogs.alert("jres:31900297"); //RC 31900297 : Je nutné uvést důvod změny aktivity subjektu.
                        }
                    });
                }
                pokusOdstraneniExSubjektu() {
                    var that = this;
                    var sel = that.gridKartoteka.ggrid("activeRow");
                    var aktivita = sel.aktivita;
                    if (sel) {
                        if (aktivita === 100) {
                            that.beginOperation();
                            that.call("PokusZmenitAktivitu", { ixs_esu: sel.ixs_esu, aktivita: aktivita })
                                .done(function (val) {
                                if (val === "Stará DB") {
                                    that.odstranitEx(100, "Neurčito"); // nedošlo ke zjištění použití v systému z důvodu staré verze databáze
                                }
                                else if (val) {
                                    that.odstranitEx(100, val); // funkce vrátí text
                                }
                                that.endOperation();
                            })
                                .fail(function (val) {
                                that.endOperation();
                            });
                        }
                        else { //aktivita == 500
                            that.odstranitEx(500, null);
                            that.endOperation();
                        }
                    }
                    else {
                        that.dialogs.alert("jres:31900144"); //RC 31900144 : Nebyl označen řádek
                    }
                }
                pridatNeboOdebratOblibene(odeber) {
                    // odeber ->   true = odebere / falsse = prida
                    var that = this;
                    //var sel = that.gridKartoteka.ggrid("getSelection")[0];
                    var sel = that.gridKartoteka.ggrid("activeRow");
                    if (sel) {
                        that.call("AddOrRemoveFavourites", { IxsEsu: sel.ixs_esu, KartSUChecked: odeber })
                            .done(function (val) {
                            that.obnovPodlePuvodnihoFiltru();
                        })
                            .fail(function (val) {
                        });
                    }
                    else {
                        that.dialogs.alert("jres:31900144"); //RC 31900144 : Nebyl označen řádek
                    }
                }
                HledatVInsolvencnimRejstriku() {
                    var that = this;
                    //var sel = that.gridKartoteka.ggrid("getSelection")[0];
                    var sel = that.gridKartoteka.ggrid("activeRow");
                    if (sel) {
                        var l_oJSONPars = {
                            ico: sel.ico, //that.findFields("Ico").gfield("getValue"),
                            rc: sel.rc, //that.findFields("RodneCislo").gfield("getValue"),
                            ixs_esu: "Podle IxsEsu načteš data",
                            dat_narozeni: undefined
                            //  nazev_osoby: sel.nazev,//that.findFields("Nazev").gfield("getValue"),
                            //  Ulice: sel.ulice,//that.findFields("Ulice").gfield("getValue").ulice_nazev,
                            //  mesto: sel.obec,//that.findFields("Obec").gfield("getValue").obec_nazev,
                            //  CPop: sel.cpop,//that.findFields("CisloPopisne").gfield("getValue"),
                        };
                        if (l_oJSONPars.ico == null && l_oJSONPars.rc == null) {
                            l_oJSONPars.dat_narozeni = sel.dat_nar;
                        }
                        if (sel.ixs_esu) {
                            l_oJSONPars.ixs_esu = sel.ixs_esu;
                        }
                        var opt = {
                            filter: l_oJSONPars
                        };
                        Gordic.Esu.Dialogs.GSeznamInsolvenceDlg(that, opt);
                    }
                    else {
                        Gordic.Esu.Dialogs.GSeznamInsolvenceDlg(that, {});
                    }
                }
                nactiZastupneOsoby(ixs_esu, filterMail) {
                    var that = this;
                    var IxsEsu = null;
                    if (ixs_esu) {
                        IxsEsu = ixs_esu;
                    }
                    else {
                        var sel = that.gridKartoteka.ggrid("activeRow");
                        if (sel) {
                            IxsEsu = sel.ixs_esu;
                        }
                    }
                    if (IxsEsu) {
                        Gordic.Esu.Utils.OtevriDialogSeZastupnymaOsobama(that, that.Ucel, IxsEsu, that.Logovani, null, { filterMail: filterMail })
                            .then(function (retVal) {
                            if (retVal && retVal.subjekty) {
                                if (that.TypZobrazeni >= 2) { // neni dodělán multiselect potom tedy jenom === 2
                                    that.prevezmiNeboPridejDoSchranky(that.upravZOhodnoty(retVal.subjekty));
                                }
                            }
                        });
                    }
                    else {
                        that.dialogs.alert("jres:31900144"); //RC 31900144 : Nebyl označen řádek
                    }
                }
                upravZOhodnoty(objArr) {
                    var that = this;
                    if (objArr != null) {
                        for (var i = 0; i < objArr.length; i++) {
                            var subjektInstance = that.ViewTabulkaSubjektu.findByKey(objArr[i].ixs_esu);
                            var subjekt = $.extend(true, {}, subjektInstance);
                            if (subjekt != null) {
                                subjekt.zo_mail = objArr[i].mail;
                                subjekt.lic = objArr[i].lic;
                                subjekt.por_zast = objArr[i].por_zast;
                                subjekt.zo_txt = objArr[i].zo_txt;
                                subjekt.zo_tel = objArr[i].tel;
                                subjekt.zo_mail = objArr[i].mail;
                                subjekt.zo_fax = objArr[i].fax;
                                subjekt.zo_zmenu_prov = objArr[i].zmenu_prov;
                                subjekt.zo_id_vnitr_adr = objArr[i].id_vnitr_adr;
                                subjekt.zo_ur_pri = objArr[i].ur_pri;
                                subjekt.typ_zo = objArr[i].typ_zo;
                                subjekt.zo_xpristup = objArr[i].pristup;
                                objArr[i] = subjekt; //  $.extend(true, subjekt ,objArr[i]); 
                            }
                        }
                    }
                    return objArr;
                }
