                adresyPobocky() {
                    var that = this;
                    var sel = that.gridKartoteka.ggrid("activeRow");
                    if (sel) {
                        var IxsDto = {
                            IxsEsu: sel.ixs_esu,
                            IxsNad: sel.ixs_nad
                        };
                        var ucel = 0; // běžný
                        if (that.Ucel >= 1) { // pokud se přebírá 
                            ucel = 1;
                        }
                        var l_oJSONPars = {
                            Ucel: ucel,
                            IxsDto: IxsDto, // IxsDto.IxsEsu  IxsDto.IxsNad   IxsDto.IxsEko
                            Logovani: this.Logovani
                        };
                        var dialog = Gordic.Esu.Dialogs.SeznamPobocekDlg(this, l_oJSONPars);
                        if (dialog) {
                            dialog.on("close", function (ev, retVal) {
                                if (retVal && retVal.subjekty && retVal.subjekty.length > 0) {
                                    that.prevezmiNeboPridejDoSchranky(retVal.subjekty);
                                }
                            });
                        }
                    }
                    else {
                        this.dialogs.alert("jres:31900144"); //RC 31900144 : Nebyl označen řádek
                    }
                }
                createPreviewPanel() {
                    var that = this;
                    return $("<div>").gpreview({
                        tabs: [
                            {
                                caption: "jres:31900321", //RC 31900321 : Souhrn
                                content: "Gordic.Esu.WebClient.GEsuDetailPreview", //časem takto-> function (loadParams) { return Gordic.Previews.getPreviewClass(loadParams.typ_ag, loadParams); }
                                userSettings: that.userSettings
                            }
                        ],
                        useSubtask: false
                    });
                }
                refreshPreview() {
                    var that = this;
                    var row = this.gridKartoteka.ggrid("activeRow");
                    if (row) {
                        this.enablePreview(true);
                        this.showPreview(row);
                    }
                    else {
                        this.enablePreview(false);
                    }
                }
                loadPreview(row) {
                    var that = this;
                    this.previewDiv.gpreview("loadAll", {
                        Logovani: that.Logovani,
                        IxsEsu: row.ixs_esu,
                        RadekZKartoteky: row
                    } /*nebo jiné dto, klidně celé row*/, true /*okamžitý reload*/);
                }
                enablePreview(enabled) {
                    this.previewDiv.gpreview("option", { disabled: !enabled });
                }
                showPreview(row) {
                    if (!this._closed && this.element.gsidebar("getPanel", "panelPreview").gsbpanel("option", "visible")) {
                        this.loadPreview(row);
                    }
                    else {
                        this.rowToPreview = row;
                    }
                }
