                prevzit(sel) {
                    var that = this;
                    if (sel == null) {
                        if (this.TypZobrazeni === 3) {
                            var view = that.gridSchranka.ggrid("getView");
                            sel = view.getDataRows(false);
                            if (sel == null || (sel != null && sel.length == 0)) {
                                sel = that.gridKartoteka.ggrid("getSelection");
                            }
                        }
                        else {
                            sel = that.gridKartoteka.ggrid("getSelection");
                        }
                    }
                    Gordic.Esu.Function.vymazLogovani();
                    this.close({ subjekty: sel }); //tryClose
                }
                prevezmiNeboPridejDoSchranky(sel) {
                    var that = this;
                    if (sel == null) {
                        sel = that.gridKartoteka.ggrid("activeRow"); // NAPOJENI  předěláno z "getSelection" na "activeRow"
                    }
                    if (this.TypZobrazeni === 3) {
                        this.pridatDoSchranky(sel);
                    }
                    else {
                        this.prevzit(sel);
                    }
                }
                pridatDoSchranky(sel) {
                    var that = this;
                    if (sel != null && sel.length > 1) {
                        var temp = [sel[0]];
                        sel = temp;
                    }
                    this.viewSchranka.updateData(sel, "set"); // místo update zde dám set
                    this.enableTasks();
                }
                odebratZeSchranky() {
                    var that = this;
                    var sel = this.gridSchranka.ggrid("getSelection");
                    if (sel && sel.length > 0) {
                        this.viewSchranka.updateData(sel, "delete");
                    }
                    this.enableTasks();
                }
