            /**
             * oveření datové schránky z Detailu Esu
             *
             * @author  Dsebesta
             * @date    03.08.2017
             *
             * @param   obj.flagGex             zda jde o gex nebo ISDS
             * @param   obj.content             content dialogu (this)
             * @param   obj.Ucel                {Detail:true}  zpusobí jen nahled
             * @param   obj.PrevzitVOkne        false vrátí data, true data rovnou uloží do esu
             * @param   obj.IxsEsu              IxsEsu
             * @param   obj.overovatJenExistenciSchranky "1" = jenom existenci
             * @return  .
             */
            function OverISDSzWFL(obj) {
                const mainDef = $.Deferred();
                // uložení hlavního promise;
                obj.mainDef = mainDef;
                obj.fromWfl = true;
                GetServer(obj.content).call("readGinsesu", { IxsEsu: obj.IxsEsu })
                    .then(function (esuDto) {
                    obj.esuDto = esuDto;
                    GetServer(obj.content).call("VratTypIsdsDleTypuOrg", { TypOrg: obj.esuDto.TypOrganizace })
                        .then(function (TypIsds) {
                        if (TypIsds) {
                            obj.TypIsds = TypIsds;
                        }
                        else {
                            obj.TypIsds = "";
                        }
                        ZadaniTypuSubjektuISDS(obj)
                            .then(function (TypIsdsSelected) {
                            HledatIsds(TypIsdsSelected, obj);
                        })
                            .fail(function (msg) {
                            mainDef.reject();
                        });
                    })
                        .fail(function (msg) {
                        mainDef.reject();
                    });
                })
                    .fail(function (msg) {
                    mainDef.reject();
                });
                return mainDef.promise();
            }
            Utils.OverISDSzWFL = OverISDSzWFL;
            //#endregion
            //#region přebírání dat z externích registru (ARES)
            function OverARES(obj) {
                const mainDef = $.Deferred();
                // uložení hlavního promise;
                obj.mainDef = mainDef;
                GetServer(obj.content).call("OvereniAres", { EsuDto: obj.esuDto })
                    .then(function (overeni) {
                    if (overeni.stav !== "-1") {
                        if (overeni.stav === "1") {
                            const $div = ExtRegistrRozdily(overeni, obj);
                            if ($div) {
                                $div.on("close", function (ev, retVal) {
                                    if (retVal) {
                                        obj.mainDef.resolve(retVal);
                                    }
                                    else {
                                        obj.mainDef.reject();
                                    }
                                });
                            }
                            else {
                                obj.mainDef.reject();
                            }
                        }
                        else if (overeni.stav === "2") {
                            obj.content.dialogs.alert("V registru nebyl dle IČO nalezen žádný záznam");
                            obj.mainDef.reject();
                        }
                    }
                    else if (overeni.zprava) {
                        obj.content.dialogs.alert(overeni.zprava);
                        obj.mainDef.reject();
                    }
                    else {
                        obj.mainDef.reject();
                    }
                })
                    .fail(function (msg) {
                    mainDef.reject();
                });
                return mainDef.promise();
            }
            Utils.OverARES = OverARES;
