            /**
             * Ověří stav eDesk schráneky.
             *
             * @author TFeik
             * @date 11.04.2019
             *
             * @param {OverEDeskSchrankuInput} input Vstupní objekt obsahující identifikátor schránky.
             * @returns {JQuery.Promise<OverEDeskSchrankuResult | undefined>} Promise vstupního objektu rozšířeného o výsledek ověření schránky.
             */
            function OverEDeskSchranku(input, content) {
                if (!input) {
                    input = {};
                }
                const result = $.extend({}, input, {
                    checkResult: 0 /* Psr.Interface.GVysledekOvereniEDeskSchrankyEnum.None */
                });
                return GetServer(content).call("OverEDeskSchranku", {
                    eDeskId: input.eDeskId
                }).then(function (overEDeskSchrankuRetVal) {
                    if (overEDeskSchrankuRetVal != undefined) {
                        result.checkResult = overEDeskSchrankuRetVal;
                    }
                    return result;
                });
            }
            Utils.OverEDeskSchranku = OverEDeskSchranku;
            /**
             * Ověří stav eDesk schránek.
             *
             * @author TFeik
             * @date 11.04.2019
             *
             * @param {OverEDeskSchrankuInput[]} inputs Pole vstupních objektů obsahující identifikátory schránek.
             * @returns {JQuery.Promise<OverEDeskSchrankuResult[]>} Promise pole vstupních objekty rozšířených o výsledky ověření schránek.
             */
            function OverEDeskSchranky(inputs, content) {
                const deferred = $.Deferred();
                const result = [];
                const itemsToCheck = $.merge([], inputs);
                function checkNext() {
                    if (itemsToCheck && itemsToCheck.length > 0) {
                        OverEDeskSchranku(itemsToCheck.shift(), content)
                            .done(function (retVal) {
                            if (retVal) {
                                result.push(retVal);
                            }
                            checkNext();
                        })
                            .fail(() => {
                            deferred.reject();
                        });
                    }
                    else {
                        deferred.resolve(result);
                    }
                }
                checkNext();
                return deferred.promise();
            }
            Utils.OverEDeskSchranky = OverEDeskSchranky;
