                _isFilterEmpty(filter) {
                    /// <summary>
                    /// Zkontroluje zda je filtr prázdný, nebo jestli je alespoň jedna hodnota filtru aktivní. Jako vyplněné hodnoty se neberou "spis_znacka2", "aktivita" a "obdobi".
                    /// </summary>
                    /// <param name="filter" type="server.GSeznamInsolvenceFilterDto">Filtr použitý pro hledání</param>
                    /// <returns type="bool">TRUE - Filtr je prázdný. FALSE - Alespoň jedna hodnota je vyplněná.</returns>
                    let index;
                    for (index in filter) {
                        if (index === "aktivita" /* GSeznamInsolvenceFilterDtoNames.aktivita */ || index === "obdobi" /* GSeznamInsolvenceFilterDtoNames.obdobi */) {
                            continue;
                        }
                        if (filter[index] != null && filter[index] !== 0 && filter[index] !== "" && filter[index] !== "0") {
                            return false;
                        }
                    }
                    return true;
                }
                /**
                 * Zkontroluje zda se oproti předchozímu hledání změnila hodnota filtru, která vyžaduje načtení nových dat ze serveru.
                 *
                 * @param {GSeznamInsolvenceFilterDto} actualFilter Filtr použitý pro aktuální hledání.
                 * @param {GSeznamInsolvenceFilterDto} previousFilter Filtr použitý pro předchozí hledání.
                 * @returns TRUE - Je nutné načíst data ze serveru. FALSE - Není potřeba načíst data ze serveru.
                 */
                _isServerFilterChanged(actualFilter, previousFilter) {
                    // Vraceni true pokud predchozi filter neexistuje - neni s cim porovnavat a je potreba nacist data znovu
                    if (!previousFilter) {
                        return true;
                    }
                    // Zazalohovani a vymazani hodnoty aktivita jednotlivych filteru pro nasledne porovnani
                    const aktivitaActualFilter = actualFilter.aktivita;
                    const aktivitaPreviousFilter = previousFilter.aktivita;
                    delete actualFilter.aktivita;
                    delete previousFilter.aktivita;
                    // Porovnani filteru bez aktivity (ktera jsou nastavena na stejnou hodnotu).
                    let result = false;
                    if (JSON.stringify(actualFilter) !== JSON.stringify(previousFilter)) {
                        result = true;
                    }
                    // Vraceni aktivity do filteru
                    actualFilter.aktivita = aktivitaActualFilter;
                    previousFilter.aktivita = aktivitaPreviousFilter;
                    return result;
                }
                /**
                 * Vrátí textový řetězec filtru pro grid dle parametrů, které nejsou filtrovány na serveru.
                 *
                 * @param {GSeznamInsolvenceFilterDto} filter Filtr použitý pro hledání.
                 * @returns Např. "aktivita == 100"
                 */
                _createClientFilterExpression(filter) {
                    let clientFilter;
                    if (filter.aktivita != null && filter.aktivita > 0) {
                        clientFilter = "aktivita == '{0}'".format(filter.aktivita);
                    }
                    return clientFilter;
                }
