                overit() {
                    this.vyhledejNaUpvsPodleKriterii();
                }
                vyhledejNaUpvsPodleKriterii() {
                    var that = this;
                    this.aktualizujDataEsuZpolicek().done(function (isValid) {
                        if (isValid) {
                            var opt = {
                                esuDto: that.esuDto
                            };
                            that.call("VyhledejNaUpvsPodleKriterii", opt)
                                .done(function (retVal) {
                                that.naplnGrid(retVal);
                            });
                        }
                    });
                }
                aktualizujDataEsuZpolicek() {
                    var that = this;
                    var promise = $.Deferred();
                    this.formular.gform("waitForValues")
                        .done(function (retval) {
                        if (that.formular.gform("isValid")) {
                            var fieldy = that.findFields(".js-orig");
                            fieldy.gfield("model", "collect", that.esuDto);
                            promise.resolve(true);
                        }
                        else {
                            promise.resolve(false);
                        }
                    })
                        .fail(function () {
                        promise.resolve(false);
                    });
                    return promise.promise();
                }
                nastavHodnotyDoOrigFormu() {
                    var that = this;
                    var fieldy = this.findFields(".js-orig");
                    fieldy.gfield("model", "apply", this.esuDto);
                }
                naplnGrid(data) {
                    var that = this;
                    this.vybranaOsoba = true;
                    this.viewTabulkaNalezenych = new Gordic.Data.View(data, { key: "IdDs" });
                    this.vysledekHledani.ggrid("setData", this.viewTabulkaNalezenych, true);
                    this.setPrvniPoNahraniNovychDat();
                }
                setPrvniPoNahraniNovychDat() {
                    var selectedRows = this.vysledekHledani.ggrid("getSelection");
                    if (selectedRows && selectedRows.length > 0) {
                        //this.VyberZRobItemsDto.AifoText = selectedRows[0].aifo;  // dsebesta 3.4.2019  přidáno dsebesta, jinak nefungovalo při prvnín dohledání možná
                        //                                                                //zpusobí kvízy jinde bude nutné rozthnout na dvě puvodní a nové AIFO
                        this.setISZRHodnoty(selectedRows[0]);
                    }
                }
                nastavHodnotyDoPolicka(hodnota, nazev, stav) {
                    if (hodnota) {
                        var field = this.findFields(nazev);
                        field.gfield("setValue", hodnota, false);
                    }
                }
                pridejStavyDoEsuRadku(hodnota, nazev, stav) {
                    if (hodnota) {
                        var field = this.findFields(nazev);
                        var ico = Gordic.Esu.Function.GetImgporovnani(stav);
                        if (ico) {
                            field.gfield("addState", ico);
                        }
                    }
                }
                setISZRHodnoty(row) {
                    var that = this;
                    this.vybranyNovyRadek();
                    this.TypEsu = row.TypEsu;
                    this.TypOrganizace = row.TypOrganizace;
                    var fieldy = this.findFields(".js-PSR");
                    fieldy.gfield("clear");
                    this.nastavHodnotyDoPolicka(row.Jmeno, "JmenoPsr", row.stav_jmeno);
                    this.nastavHodnotyDoPolicka(row.Prijmeni, "PrijmeniPsr", row.stav_prijmeni);
                    this.nastavHodnotyDoPolicka(row.Nazev, "NazevPsr", row.stav_nazev);
                    this.nastavHodnotyDoPolicka(row.ObchodniJmeno, "ObchodniJmenoPsr", row.stav_ob_jmeno);
                    this.nastavHodnotyDoPolicka(row.DatNar, "DatNarozeniPsr", row.stav_datum_naroz);
                    this.nastavHodnotyDoPolicka(row.DatUmrti, "DatUmrtiPsr", row.stav_dat_umrti);
                    this.nastavHodnotyDoPolicka(row.IdDs, "IDDSPsr", row.stav_id_ds);
                    this.nastavHodnotyDoPolicka(row.SkEdeskId, "SkEdeskIdPsr", row.stav_sk_edesk_id);
                    this.nastavHodnotyDoPolicka(row.Ico, "IcoPsr", row.stav_ico);
                    this.nastavHodnotyDoPolicka(row.RodneCislo, "RodneCisloPsr", row.stav_rodneCislo);
                    this.nastavHodnotyDoPolicka({ stat: row.StatSp }, "StatSpPsr", row.stav_sp);
                    this.nastavHodnotyDoPolicka(row.Obec, "ObecPsr", row.stav_obec);
                    this.nastavHodnotyDoPolicka(row.CastObce, "CastObcePsr", row.stav_cast_obce);
                    this.nastavHodnotyDoPolicka(row.Ulice, "UlicePsr", row.stav_ulice);
                    this.nastavHodnotyDoPolicka(row.CisloPopisne, "CPopisnePsr", row.stav_cislo_popisne);
                    this.nastavHodnotyDoPolicka(row.CisloOrientacni, "COrientacniPsr", row.stav_cislo_orientacni);
                    this.nastavHodnotyDoPolicka(row.Psc, "PscPsr", row.stav_psc);
                    this.nastavHodnotyDoPolicka({ stat: row.Stat }, "StatPsr", row.stav_stat);
                    //this.nastavHodnotyDoPolicka(row., "COrientPismPsr", row.stav_prijmeni);
                    this.nastavHodnotyDoPolicka({ klic: row.eDeskStatus }, "eDeskStatusPsr", row.eDeskStatus);
                    this.pridejStavyDoEsuRadku(row.Jmeno, "Jmeno", row.stav_jmeno);
                    this.pridejStavyDoEsuRadku(row.Prijmeni, "Prijmeni", row.stav_prijmeni);
                    this.pridejStavyDoEsuRadku(row.Nazev, "Nazev", row.stav_nazev);
                    this.pridejStavyDoEsuRadku(row.ObchodniJmeno, "ObchodniJmeno", row.stav_ob_jmeno);
                    this.pridejStavyDoEsuRadku(row.DatNar, "DatNar", row.stav_datum_naroz);
                    this.pridejStavyDoEsuRadku(row.DatUmrti, "DatUmrti", row.stav_dat_umrti);
                    this.pridejStavyDoEsuRadku(row.IdDs, "IdDs", row.stav_id_ds);
                    this.pridejStavyDoEsuRadku(row.SkEdeskId, "SkEdeskId", row.stav_sk_edesk_id);
                    this.pridejStavyDoEsuRadku(row.Ico, "Ico", row.stav_ico);
                    this.pridejStavyDoEsuRadku(row.RodneCislo, "RodneCislo", row.stav_rodneCislo);
                    this.pridejStavyDoEsuRadku({ stat: row.StatSp }, "StatSp", row.stav_sp);
                    this.pridejStavyDoEsuRadku(row.Obec, "Obec", row.stav_obec);
                    this.pridejStavyDoEsuRadku(row.CastObce, "CastObce", row.stav_cast_obce);
                    this.pridejStavyDoEsuRadku(row.Ulice, "Ulice", row.stav_ulice);
                    this.pridejStavyDoEsuRadku(row.CisloPopisne, "CisloPopisne", row.stav_cislo_popisne);
                    this.pridejStavyDoEsuRadku(row.CisloOrientacni, "CisloOrientacni", row.stav_cislo_orientacni);
                    this.pridejStavyDoEsuRadku(row.Psc, "Psc", row.stav_psc);
                    this.pridejStavyDoEsuRadku({ stat: row.Stat }, "Stat", row.stav_stat);
                }
                getImgStavSpravny(stav) {
                    if (stav === 0)
                        return { id: "ico", icon: "gi-tick", customClass: "g-state-success", tooltip: "✓ " + "jres:31900290" }; //RC 31900290 : Ověřeno
                    else if (stav === 1 || stav === 2)
                        return { id: "ico", icon: "gi-window-close", customClass: "g-state-important", tooltip: "✗ " + "jres:31900616" }; //RC 31900616 : Neověřeno
                    else
                        return null;
                }
                vybranyNovyRadek() {
                    this.odstranPorovnavaciIkonky();
                    this.odstranISZRIkonky();
                }
                odstranISZRIkonky() {
                    this.findFields(".js-PSR").each(function (imdex, field) {
                        var stat = $(field).gfield("getState", "ico");
                        if (stat && stat.length > 0)
                            stat.remove();
                    });
                }
                odstranPorovnavaciIkonky() {
                    this.findFields(".js-origCompareIco").each(function (imdex, field) {
                        var stat = $(field).gfield("getState", "icoCompare");
                        if (stat && stat.length > 0)
                            stat.remove();
                    });
                }
